"""Create the self-contained local alignment annotation pilot notebook."""
import nbformat as nb

book = nb.v4.new_notebook()
md, code = nb.v4.new_markdown_cell, nb.v4.new_code_cell
book.cells = [
    md('# 16.7 - Frontal alignment annotation pilot\n\nPrepare a local review packet. Candidate photographs are not confirmed frontal views or target labels. Do not publish images while redistribution terms are unverified.'),
    code('from pathlib import Path\nimport hashlib\nimport pandas as pd\nfrom PIL import Image\nimport matplotlib.pyplot as plt\nroot = Path.cwd().resolve()\nwhile not (root / "AGENTS.md").exists():\n    if root == root.parent: raise RuntimeError("Project root not found")\n    root = root.parent\npilot = root / "data/processed/alignment_omni_pilot"\nsource = pd.read_csv(pilot / "pilot_provenance.csv", dtype={"source_image_id": str, "sha256": str})\nprint("Pilot records:", len(source))\ndisplay(source.groupby("split").size().to_frame("images"))'),
    md('## Verify source images\n\nCheck SHA-256 and dimensions for each image; preserve the source split. A filename suffix is only a prioritization heuristic.'),
    code('records = []\nfor r in source.to_dict("records"):\n    path = pilot / "images" / r["split"] / (r["source_image_id"] + ".jpg")\n    digest = hashlib.sha256(path.read_bytes()).hexdigest()\n    assert digest == r["sha256"], f"Hash mismatch: {path}"\n    with Image.open(path) as im: width, height = im.size\n    records.append({**r, "image_path": path.relative_to(root).as_posix(), "width": width, "height": height})\nverified = pd.DataFrame(records)\nassert len(verified) == 36 and not verified.sha256.duplicated().any()\nprint("Verified images:", len(verified))\ndisplay(verified.groupby("split")[["width", "height"]].agg(["min", "median", "max"]))'),
    md('## Prepare review and annotation files\n\nA reviewer must independently determine view and target status. Record present, absent or uncertain; an omitted box does not mean absent. Review the pilot with a dental professional before bulk annotation. Existing review files are never overwritten.'),
    code('out = root / "docs/reports/alignment/frontal_pilot_16_7"\nout.mkdir(parents=True, exist_ok=True)\nqueue = verified[["split", "source_image_id", "image_path", "sha256", "width", "height"]].copy()\nfor field in ["view_review", "dentition_review", "diastema_review", "crowding_review", "reviewer", "review_notes"]: queue[field] = "pending"\nqueue_path = out / "review_queue.csv"\nif not queue_path.exists(): queue.to_csv(queue_path, index=False)\nelse: print("Preserving existing review queue")\nbox_path = out / "boxes_template.csv"\nif not box_path.exists():\n    pd.DataFrame(columns=["source_image_id", "target", "x_min", "y_min", "x_max", "y_max", "reviewer", "review_state", "notes"]).to_csv(box_path, index=False)\nelse: print("Preserving existing box annotations")\ndisplay(queue.head())'),
    md('## Annotation protocol\n\nUse original-image pixel coordinates. For upper midline diastema, include the central incisors surrounding the visible gap. For anterior crowding, include affected anterior teeth and their neighbors. Record uncertain cases rather than guessing. This working protocol is adapted from [the YOLO11 malocclusion study](https://pmc.ncbi.nlm.nih.gov/articles/PMC12839579/) and must be reviewed for this dataset.'),
    md('## Contact sheets\n\nExamine each candidate for frontal suitability and image quality. These local sheets are review aids, not model predictions or clinical labels.'),
    code('for split, group in verified.groupby("split"):\n    for start in range(0, len(group), 12):\n        chunk = group.iloc[start:start + 12]\n        fig, axes = plt.subplots(3, 4, figsize=(16, 11))\n        axes = axes.flatten()\n        for ax, (_, row) in zip(axes, chunk.iterrows()):\n            ax.imshow(Image.open(root / row.image_path))\n            ax.set_title(row.source_image_id, fontsize=9)\n            ax.axis("off")\n        for ax in axes[len(chunk):]: ax.axis("off")\n        fig.suptitle(f"{split}: candidate images - review pending")\n        fig.tight_layout()\n        fig.savefig(out / f"{split}_{start // 12 + 1}.png", dpi=120)\n        plt.show()\n        plt.close(fig)\nprint("Review packet:", out)')
]
book.metadata.kernelspec = {'display_name': 'DentalSelfie', 'language': 'python', 'name': 'dentalselfie-local'}
nb.write(book, 'notebooks/alignment/16_7_frontal_annotation_pilot.ipynb')
